document.addEventListener("DOMContentLoaded",c=>{((r,s)=>{document.querySelectorAll(r).forEach(e=>{fetch(e.src).then(t=>t.text()).then(t=>{const n=new DOMParser().parseFromString(t,"image/svg+xml").querySelector("svg");e.id&&(n.id=e.id),e.className&&(n.classList=e.classList),e.parentNode.replaceChild(n,e)}).then(s).catch(t=>console.error(t))})})("img.svg-icon")});document.addEventListener("DOMContentLoaded",c=>{const o=document.querySelector("html");window.location.hash!=""?o.style.scrollBehavior="auto":o.style.scrollBehavior="smooth",document.querySelectorAll('a[href^="#"]').forEach(r=>{r.onclick=function(s){s.preventDefault(),window.scrollTo({top:document.querySelector(this.getAttribute("href")).offsetTop,behavior:"smooth"})}})});
